<script setup lang="ts">
import {onMounted,ref} from 'vue';import {request,resolveSession,restoreTask} from './api';
const modes=ref<any[]>([]),faults=ref<any[]>([]),session=ref(''),task=ref<any>(null),dashboard=ref<any>({}),goal=ref('诊断所选合成故障并在完成后恢复'),scenario=ref('normal'),scenarioId=ref('F323'),busy=ref(false),error=ref('');
async function refresh(){dashboard.value=await request('/api/dashboard');if(task.value)task.value=await request('/api/tasks/'+task.value.task_id)}
async function ensureSession(){session.value=await resolveSession(session.value,localStorage)}
async function run(){busy.value=true;error.value='';try{await ensureSession();const r=await request('/api/tasks',{method:'POST',body:JSON.stringify({session_id:session.value,goal:goal.value,scenario:scenario.value,scenario_id:scenarioId.value})});localStorage.setItem('mvp2_task_id',r.task_id);task.value=await request('/api/tasks/'+r.task_id);await refresh()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(async()=>{try{const catalog=await request('/api/scenarios');modes.value=catalog.demo_modes;faults.value=catalog.fault_scenarios;session.value=localStorage.getItem('mvp2_session_id')||'';await ensureSession();task.value=await restoreTask(localStorage.getItem('mvp2_task_id'),localStorage);await refresh()}catch(e:any){error.value=e.message}});
</script>
<template><main><header><div><p class="eyebrow">AUTOFAULT-AGENT 2.0 · MVP-2.1</p><h1>合成诊断 Runtime 控制台</h1><p>确定性脚本驱动 · 真实 Harness · 内存合成 DUT · 不执行大模型推理 · 不连接真实 ECU</p></div><span class="badge">Deterministic Scripted Runtime</span></header>
<section class="stats"><article><b>{{dashboard.running||0}}</b><span>运行中</span></article><article><b>{{dashboard.completed||0}}</b><span>已完成</span></article><article><b>{{dashboard.failed||0}}</b><span>安全终止</span></article><article><b>{{dashboard.tool_calls||0}}</b><span>工具调用</span></article><article><b>{{dashboard.sessions||0}}</b><span>Session</span></article></section>
<div class="grid"><section class="panel submit"><h2>提交诊断任务</h2><label>故障场景<select v-model="scenarioId"><option v-for="s in faults" :value="s.id">{{s.label}}</option></select></label><label>演示模式<select v-model="scenario"><option v-for="s in modes" :value="s.id">{{s.label}}</option></select></label><label>任务目标<textarea v-model="goal" rows="4"/></label><button :disabled="busy" @click="run">{{busy?'执行中…':'启动合成 Runtime'}}</button><p class="error">{{error}}</p><small>工具顺序由确定性演示脚本驱动；不代表模型自主规划或能力提升。</small><small v-if="task">Task ID：{{task.task_id}}</small></section>
<section class="panel"><h2>Runtime Inspector</h2><div v-if="task" class="kv"><span>状态</span><b>{{task.status}}</b><span>Session</span><code>{{task.session_id}}</code><span>DUT</span><code>{{task.final_state?.state}}</code><span>场景</span><code>{{task.scenario}}</code></div><p v-else>提交任务后显示服务端权威状态。</p></section></div>
<section class="panel" v-if="task"><h2>执行时间线</h2><ol class="timeline"><li v-for="e in task.events"><i></i><div><b>{{e.event_type}}</b><span>{{e.tool_name||''}} · {{e.status}}</span><p>{{e.sanitized_summary}}</p><small v-if="e.operation_id">Operation：{{e.operation_id}} · Action：{{e.action_id}} · Side effects：{{e.side_effect_count}}</small></div></li></ol></section>
<div class="grid" v-if="task"><section class="panel"><h2>Context Inspector</h2><div class="kv"><span>Token 模式</span><b>{{task.context?.token_statistics?.token_count_mode}}</b><span>统计范围</span><code>{{task.context?.token_statistics?.token_count_scope}}</code><span>Tokenizer</span><code>{{task.context?.token_statistics?.tokenizer_name||task.context?.token_statistics?.tokenizer_source}}</code><span>原始序列化消息 Token</span><code>{{task.context?.token_statistics?.original_tokens}}</code><span>分项序列化上下文 Token 合计</span><code>{{task.context?.token_statistics?.compressed_tokens}}</code><span>压缩率</span><code>{{task.context?.token_statistics?.compression_ratio ?? '不可直接比较（统计范围不同）'}}</code><span>预留输出 / 可用预算</span><code>{{task.context?.token_statistics?.reserved_output_tokens}} / {{task.context?.token_statistics?.available_context_budget}}</code></div><p><small v-if="task.context?.token_statistics?.token_count_mode==='exact'">EXACT 表示指定 Tokenizer 对序列化数据的精确计数，不代表 Chat Template 后的实际 Prompt Token 数。</small><small v-else>ESTIMATED 为启发式估算，不是精确 Token 计数。</small></p><pre>{{JSON.stringify(task.context,null,2)}}</pre></section><section class="panel"><h2>Action Ledger</h2><pre>{{JSON.stringify(task.actions,null,2)}}</pre></section></div></main></template>
